/**
 * Configuration for SR-MPLS with Label, TC, Bottom-of-Stack and TTL.
 */
export interface BgpSrteSrMplsSid {
  /**
   * Label value in [0, 2^20 -1].
   */
  label?: number;

  /**
   * Bottom-of-Stack bit.
   */
  s_bit?: boolean;

  /**
   * Traffic class in bits.
   */
  tc?: number;

  /**
   * Time To Live.
   */
  ttl?: number;
}

/**
 * Configuration for BGP Segment Routing Traffic Engineering(SRTE) policy.
 */
export interface BgpSrteV4Policy {
  /**
   * Specifies a single node or a set of nodes (e.g. an anycast address). It is
   * selected on the basis of the SR Policy type (AFI).
   */
  ipv4_endpoint: string;

  /**
   * Globally unique name of an object. It also serves as the primary key for arrays
   * of objects.
   */
  name: string;

  /**
   * If enabled means that this part of the configuration including any active
   * 'children' nodes will be advertised to peer. If disabled, this means that though
   * config is present, it is not taking any part of the test but can be activated at
   * run-time to advertise just this part of the configuration to the peer.
   */
  active?: boolean;

  /**
   * The BGP Additional Paths feature is a BGP extension that allows the
   * advertisement of multiple paths for the same prefix without the new paths
   * implicitly replacing any previous paths.
   */
  add_path?: BgpAddPath;

  /**
   * Configuration for advanced BGP route range settings.
   */
  advanced?: BgpRouteAdvanced;

  /**
   * This attribute identifies the autonomous systems through which routing
   * information carried in this UPDATE message has passed. This contains the
   * configuration of how to include the Local AS in the AS path attribute of the MP
   * REACH NLRI. It also contains optional configuration of additional AS Path
   * Segments that can be included in the AS Path attribute. The AS Path consists of
   * a Set or Sequence of Autonomous Systems (AS) numbers that a routing information
   * passes through to reach the destination.
   */
  as_path?: BgpAsPath;

  /**
   * Policy color is used to match the color of the destination prefixes to steer
   * traffic into the SR Policy.
   */
  color?: number;

  /**
   * Optional Community settings.
   */
  communities?: Array<BgpCommunity>;

  /**
   * 4-octet value uniquely identifying the policy in the context of (color,
   * endpoint) tuple. It is used by the SR Policy originator to make unique (from an
   * NLRI perspective) both for multiple candidate paths of the same SR Policy as
   * well as candidate paths of different SR Policies (i.e. with different segment
   * list) with the same Color and Endpoint but meant for different head-ends.
   */
  distinguisher?: number;

  /**
   * Optional Extended Community settings. The Extended Communities Attribute is a
   * transitive optional BGP attribute, with the Type Code 16. Community and Extended
   * Communities attributes are utilized to trigger routing decisions, such as
   * acceptance, rejection, preference, or redistribution. An extended community is
   * an 8-Bytes value. It is divided into two main parts. The first 2 Bytes of the
   * community encode a type and sub-type fields and the last 6 Bytes carry a unique
   * set of data in a format defined by the type and sub-type field. Extended
   * communities provide a larger range for grouping or categorizing communities.
   * When type is administrator_as_2octet or administrator_as_4octet, the valid sub
   * types are route target and origin. The valid value for administrator_as_2octet
   * and administrator_as_4octet type is either two byte AS followed by four byte
   * local administrator id or four byte AS followed by two byte local administrator
   * id. When type is administrator_ipv4_address the valid sub types are route target
   * and origin. The valid value for administrator_ipv4_address is a four byte IPv4
   * address followed by a two byte local administrator id. When type is opaque,
   * valid sub types are color and encapsulation. When sub type is color, first two
   * bytes of the value field contain flags and last four bytes contains the value of
   * the color. When sub type is encapsulation the first four bytes of value field
   * are reserved and last two bytes carries the tunnel type from IANA's "ETHER
   * TYPES" registry e.g IPv4 (protocol type = 0x0800), IPv6 (protocol type =
   * 0x86dd), and MPLS (protocol type = 0x8847). When type is
   * administrator_as_2octet_link_bandwidth the valid sub type is extended_bandwidth.
   * The first two bytes of the value field contains the AS number and the last four
   * bytes contains the bandwidth in IEEE floating point format. When type is evpn
   * the valid subtype is mac_address. In the value field the low-order bit of the
   * first byte(Flags) is defined as the "Sticky/static" flag and may be set to 1,
   * indicating the MAC address is static and cannot move. The second byte is
   * reserved and the last four bytes contain the sequence number which is used to
   * ensure that PEs retain the correct MAC/IP Advertisement route when multiple
   * updates occur for the same MAC address.
   */
  ext_communities?: Array<BgpExtCommunity>;

  /**
   * Type of next hop IP address to be used when 'next_hop_mode' is set to 'manual'.
   */
  next_hop_address_type?: 'ipv4' | 'ipv6';

  /**
   * The IPv4 address of the next hop if the Nexthop type 'next_hop_mode' is 'manual'
   * and the Nexthop type 'next_hop_address_type' is IPv4. If BGP peer is of type
   * IPv6, Nexthop Encoding capability extended_next_hop_encoding should be enabled.
   */
  next_hop_ipv4_address?: string;

  /**
   * The IPv6 address of the next hop if the Nexthop Mode 'next_hop_address_type' is
   * 'manual' and the Nexthop type 'next_hop_address_type' is IPv6.
   */
  next_hop_ipv6_address?: string;

  /**
   * Mode for choosing the NextHop in MP REACH NLRI. Available modes are : Local IP:
   * Automatically fills the Nexthop with the Local IP of the BGP peer. For IPv6 BGP
   * peer the Nexthop Encoding capability should be enabled. Manual: Override the
   * Nexthop with any arbitrary IPv4/IPv6 address.
   */
  next_hop_mode?: 'local_ip' | 'manual';

  /**
   * List Tunnel Encapsulation Attributes.
   */
  tunnel_tlvs?: Array<BgpSrteV4Policy.TunnelTlv>;
}

export namespace BgpSrteV4Policy {
  /**
   * Configuration for BGP SRTE Tunnel TLV.
   */
  export interface TunnelTlv {
    /**
     * Globally unique name of an object. It also serves as the primary key for arrays
     * of objects.
     */
    name: string;

    /**
     * If enabled means that this part of the configuration including any active
     * 'children' nodes will be advertised to peer. If disabled, this means that though
     * config is present, it is not taking any part of the test but can be activated at
     * run-time to advertise just this part of the configuration to the peer.
     */
    active?: boolean;

    /**
     * Configuration for the binding SID sub-TLV. This is used to signal the binding
     * SID related information of the SR Policy candidate path.
     */
    binding_sub_tlv?: ConfigAPI.BgpSrteBindingSubTlv;

    /**
     * Configuration for the Policy Color attribute sub-TLV. The Color sub-TLV MAY be
     * used as a way to "color" the corresponding Tunnel TLV. The Value field of the
     * sub-TLV is eight octets long and consists of a Color Extended Community. First
     * two octets of its Value field are 0x030b as type and subtype of extended
     * community. Remaining six octets are are exposed to configure.
     */
    color_sub_tlv?: ConfigAPI.BgpSrteColorSubTlv;

    /**
     * Configuration for BGP explicit null label policy sub TLV settings.
     */
    explicit_null_label_policy_sub_tlv?: ConfigAPI.BgpSrteExplicitNullLabelPolicySubTlv;

    /**
     * Configuration for the Policy Name sub-TLV. The Policy Name sub-TLV is used to
     * attach a symbolic name to the SR Policy candidate path.
     */
    policy_name_sub_tlv?: ConfigAPI.BgpSrtePolicyNameSubTlv;

    /**
     * Configuration for the Policy Priority sub-TLV. The Policy Priority to indicate
     * the order in which the SR policies are re-computed upon topological change.
     */
    policy_priority_sub_tlv?: ConfigAPI.BgpSrtePolicyPrioritySubTlv;

    /**
     * Configuration for BGP preference sub TLV of the SR Policy candidate path.
     */
    preference_sub_tlv?: ConfigAPI.BgpSrtePreferenceSubTlv;

    /**
     * Configuration for the BGP remote endpoint sub TLV.
     */
    remote_endpoint_sub_tlv?: ConfigAPI.BgpSrteRemoteEndpointSubTlv;

    segment_lists?: Array<ConfigAPI.BgpSrteSegmentList>;
  }
}

