    speed?:
      | 'speed_10_fd_mbps'
      | 'speed_10_hd_mbps'
      | 'speed_100_fd_mbps'
      | 'speed_100_hd_mbps'
      | 'speed_1_gbps'
      | 'speed_10_gbps'
      | 'speed_25_gbps'
      | 'speed_40_gbps'
      | 'speed_50_gbps'
      | 'speed_100_gbps'
      | 'speed_200_gbps'
      | 'speed_400_gbps'
      | 'speed_800_gbps';
